        // sceAgcDriverAddEqEvent.
        public ulong CompletionEventId { get; set; }
        public ulong ActiveSubmissionId { get; set; }
        public Queue<PendingSubmission> PendingSubmissions { get; } = new();
        public bool HasActiveSubmission { get; set; }
